package com.aadil.ecommerce.services;import com.aadil.ecommerce.dtos.OrderInCartDTO;import com.aadil.ecommerce.dtos.OrderRequestDTO;import com.aadil.ecommerce.entities.OrderEntity;import com.aadil.ecommerce.entities.OrderItemEntity;import com.aadil.ecommerce.entities.ProductEntity;import com.aadil.ecommerce.entities.UserEntity;import com.aadil.ecommerce.enums.OrderStatus;import com.aadil.ecommerce.exceptions.InsufficientStockException;import com.aadil.ecommerce.exceptions.ProductNotFoundException;import com.aadil.ecommerce.exceptions.UserNotFoundException;import com.aadil.ecommerce.repositories.OrderItemRepository;import com.aadil.ecommerce.repositories.OrderRepository;import com.aadil.ecommerce.repositories.ProductRepository;import com.aadil.ecommerce.repositories.UserRepository;import com.aadil.ecommerce.responses.OrderResponse;import com.aadil.ecommerce.responses.OrderResponseMapper;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.ArrayList;import java.util.List;@Service@RequiredArgsConstructorpublic class OrderService {    private final UserRepository userRepository;    private final ProductRepository productRepository;    private final OrderRepository orderRepository;    private final OrderItemRepository orderItemRepository;    private final OrderResponseMapper orderResponseMapper;    @Transactional    public OrderResponse createOrder (OrderInCartDTO dto){        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();        String email = authentication.getName().trim().toLowerCase();        UserEntity user = userRepository.findByEmail(email).orElseThrow(()->new UserNotFoundException("User NOT found: "+email));        OrderEntity order = new OrderEntity();        order.setUser(user);        order.setTotalAmount(BigDecimal.ZERO);        order.setOrderStatus(OrderStatus.PENDING);        orderRepository.save(order);        List<OrderItemEntity> orderedItems = new ArrayList<>();        BigDecimal totalAmount = BigDecimal.ZERO;        for (OrderRequestDTO orders : dto.getOrderItems()){            ProductEntity product = productRepository.findById(orders.getProductId()).orElseThrow(()->new ProductNotFoundException("Product NOT found"));            if (orders.getQuantity() > product.getStockQuantity()){                throw new InsufficientStockException("Insufficient stock of products");            }            BigDecimal unitPrice = product.getPrice();             BigDecimal price = unitPrice.multiply(BigDecimal.valueOf(orders.getQuantity()));             OrderItemEntity orderItem = new OrderItemEntity();             orderItem.setOrder(order);             order.getOrderItems().add(orderItem);             orderItem.setProduct(product);             orderItem.setUnitPrice(unitPrice);             orderItem.setQuantity(orders.getQuantity());             totalAmount = totalAmount.add(price);             order.setTotalAmount(totalAmount);             product.setStockQuantity(product.getStockQuantity() - orderItem.getQuantity());        }        orderItemRepository.saveAll(orderedItems);        productRepository.saveAll(orderedItems.stream().map(OrderItemEntity::getProduct).toList());        return orderResponseMapper.mapToResponse(order);    }}